 {id:'PL-2025-053',type:'event',status:'rejected',date:'06 Okt 2025',name:'Rania Aditya',fields:{name:'Rania Aditya',eventName:'Lokakarya Kreatif',organizer:'Komunitas Mahasiswa',eventDate:'2025-10-10',location:'Ruang A-101',purpose:'Lokakarya',responsible:'Rania Aditya'},note:'Waktu kegiatan telah lewat saat pengajuan diperiksa.',timeline:[{title:'Pengajuan dikirim',actor:'Rania Aditya',date:'06 Okt 2025 · 10.10'},{title:'Pengajuan ditolak',actor:'Dimas Pratama · Verifikator',date:'07 Okt 2025 · 13.50',note:'Waktu kegiatan telah lewat saat pengajuan diperiksa.'}]}
