const defaultState={role:'pengaju',page:'dashboard',requests:seed,selectedId:'PL-2025-084',filter:'all',query:'',month:'Oktober 2025',services:{active:5,event:8,facility:6},paperCost:280,printing:180,gridFactor:709,transfer:.42};
let state;try{state={...defaultState,...JSON.parse(localStorage.getItem('paperless-demo-state')||'{}')};if(!Array.isArray(state.requests))state.requests=seed}catch{state={...defaultState,requests:seed}};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const view=$('#view');let toastTimer,modalAction=null;
function persist(){localStorage.setItem('paperless-demo-state',JSON.stringify(state))}
function toast(message){$('#toastText').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function status(s){let x=STATUS[s]||STATUS.draft;return `<span class="status status-${x[1]}">${x[0]}</span>`}
function serviceName(type){return SERVICE[type]||SERVICE.active}
function navHref(page){return `#${page}`}
function renderNav(){const items=NAV[state.role];$('#sideNav').innerHTML=items.map(([ic,label,page])=>`<a class="nav-link ${state.page===page?'active':''}" href="${navHref(page)}"><span class="nav-icon">${ICONS[ic]}</span><span>${label}</span>${page==='queue'&&pendingCount()?`<span class="nav-count">${pendingCount()}</span>`:''}</a>`).join('');$('#mobileNav').innerHTML=items.slice(0,4).map(([ic,label,page])=>`<a class="${state.page===page?'active':''}" href="${navHref(page)}"><span>${ICONS[ic]}</span><span>${label.split(' ')[0]}</span></a>`).join('');const current=items.find(x=>x[2]===state.page);$('#crumbTitle').textContent=current?.[1]||'Ringkasan';$('#roleSelect').value=state.role;const user=USERS[state.role];$('#profileName').textContent=user.name;$('#profileRole').textContent=user.sub;$('#topUserName').textContent=user.name;$('#roleAvatar').textContent=user.initials;document.querySelectorAll('.avatar').forEach(x=>x.textContent=user.initials);}
function pendingCount(){return state.requests.filter(r=>['submitted','in_review'].includes(r.status)).length}
function requestRows(items){return items.map(r=>`<tr><td><span class="request-id">${r.id}</span><span class="service-name">${serviceName(r.type)}</span></td><td>${esc(r.name)}</td><td>${r.date}</td><td>${status(r.status)}</td><td><button class="action-link" data-open="${r.id}">Lihat detail →</button></td></tr>`).join('')}
function mobileRequestCards(items){return `<div class="table-mobile">${items.map(r=>`<div class="mobile-request"><div class="mobile-request-top"><div><b>${r.id}</b><small>${serviceName(r.type)}</small></div>${status(r.status)}</div><div class="mobile-request-bottom"><small>${esc(r.name)} · ${r.date}</small><button class="action-link" data-open="${r.id}">Lihat detail →</button></div></div>`).join('')}</div>`}
function recentTable(items,review=false){return `<div class="table-wrap"><table><thead><tr><th>ID PENGAJUAN</th>${review?'<th>PENGAJU</th>':'<th>LAYANAN</th>'}<th>${review?'DITERIMA':'TANGGAL'}</th><th>STATUS</th><th></th></tr></thead><tbody>${items.map(r=>`<tr><td><span class="request-id">${r.id}</span><span class="service-name">${serviceName(r.type)}</span></td><td>${review?esc(r.name):serviceName(r.type)}</td><td>${r.date}</td><td>${status(r.status)}</td><td><button class="action-link" data-open="${r.id}">Lihat →</button></td></tr>`).join('')}</tbody></table></div>${mobileRequestCards(items)}`}
function header(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function primaryLink(page,label,icon=''){return `<a class="button button-primary" href="#${page}">${icon?`<span class="icon-add">${icon}</span>`:''}<span class="button-label">${label}</span></a>`}
function stat(label,value,foot,icon,trend=''){return `<article class="card stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<span class="trend">${trend}</span> `:''}${foot}</div></article>`}
function renderDashboard(){const mine=state.requests.filter(r=>r.name==='Rania Aditya');const recent=mine.slice(0,4);return `${header('RINGKASAN PENGAJU','Selamat pagi, Rania 👋','Pantau pengajuan administrasi dan temukan layanan yang kamu butuhkan.',primaryLink('new','Buat Pengajuan','＋'))}<section class="welcome-card"><div class="welcome-copy"><div class="welcome-kicker">Senin, 27 Oktober 2025 · Semester Ganjil</div><h2>Administrasi kampus, lebih mudah dari sebelumnya.</h2><p>Semua pengajuanmu tersimpan rapi dan bisa dipantau dalam satu tempat.</p><a class="button button-light" href="#requests">Lihat riwayat <span>→</span></a></div><div class="welcome-art" aria-hidden="true"><div class="art-orbit"></div><div class="paper-card"><div class="paper-lines"></div><div class="paper-lines"></div><div class="paper-lines"></div><div class="paper-lines"></div></div><div class="file-card"><div class="paper-lines"></div><div class="paper-lines"></div><div class="paper-lines"></div></div><span class="spark one">✳</span><span class="spark two">✦</span></div></section><div class="stats-grid">${stat('Total pengajuan',mine.length,'sepanjang periode ini','▤')}${stat('Dalam proses',mine.filter(r=>['submitted','in_review','revision_requested'].includes(r.status)).length,'menunggu tindak lanjut','◷')}${stat('Telah disetujui',mine.filter(r=>r.status==='approved').length,'dokumen di arsip digital','✓')}${stat('Rata-rata proses','1,8 hari','data simulasi demo','◷')}</div><div class="content-grid"><section class="card section-card"><div class="section-head"><div><h3>Pengajuan terbaru</h3><p>Perkembangan permohonan administrasimu</p></div><a class="text-link" href="#requests">Lihat semua →</a></div>${recent.length?recentTable(recent):empty('Belum ada pengajuan','Mulai dengan memilih salah satu layanan administrasi.')}</section><section class="card section-card"><div class="section-head"><div><h3>Layanan administrasi</h3><p>Pilih layanan yang kamu perlukan</p></div></div><div class="service-list">${[['active','▧','Surat Keterangan Aktif Kuliah','Surat untuk keperluan akademik'],['event','✳','Surat Izin Kegiatan','Ajukan izin kegiatan kampus'],['facility','⌂','Peminjaman Fasilitas','Gunakan ruang dan fasilitas kampus']].map(([key,icon,name,desc])=>`<a class="service-item" href="#new" data-service="${key}"><span class="service-icon">${icon}</span><span class="service-text"><b>${name}</b><span>${desc}</span></span><span class="service-arrow">›</span></a>`).join('')}</div></section></div><div class="impact-strip"><span class="impact-symbol">✳</span><div><b>Dampak yang transparan, dimulai dari proses yang ringkas.</b><p>Lihat bagaimana estimasi penggunaan kertas dihitung — beserta asumsi dan batasannya.</p></div><a href="#impact">Jelajahi dampak →</a></div>`}
function empty(title,desc,button=''){return `<div class="empty-state"><div class="empty-icon">▤</div><b>${title}</b><p>${desc}</p>${button}</div>`}
function renderRequests(){let items=state.requests.filter(r=>r.name==='Rania Aditya');if(state.filter!=='all')items=items.filter(r=>r.status===state.filter);if(state.query)items=items.filter(r=>(r.id+serviceName(r.type)+r.status).toLowerCase().includes(state.query.toLowerCase()));return `${header('RUANG PENGAJU','Riwayat Pengajuan','Semua permohonan administrasi dalam satu daftar yang mudah ditelusuri.',primaryLink('new','Buat Pengajuan','＋'))}<section class="card requests-card"><div class="filter-row"><label class="search-control"><span>⌕</span><input id="requestSearch" placeholder="Cari ID atau layanan…" value="${esc(state.query)}"></label><select class="control" id="statusFilter"><option value="all">Semua status</option>${Object.entries(STATUS).map(([key,val])=>`<option value="${key}" ${state.filter===key?'selected':''}>${val[0]}</option>`).join('')}</select><span class="filter-spacer"></span><span class="subtle-label">${items.length} pengajuan</span></div>${items.length?recentTable(items):empty('Tidak ada pengajuan ditemukan','Coba ubah kata kunci atau filter status.',`<button class="button button-quiet" id="clearFilters">Hapus filter</button>`)}<div class="pagination"><span>Menampilkan ${items.length?1:0}–${items.length} dari ${items.length} pengajuan</span><div class="pagination-controls"><button aria-label="Halaman sebelumnya" disabled>‹</button><button>1</button><button aria-label="Halaman berikutnya" disabled>›</button></div></div></section>`}
function field(name,label,value='',type='text',opts=[]){let id=`field-${name}`;return `<div class="field" data-field="${name}"><label for="${id}">${label}</label>${type==='select'?`<select id="${id}" name="${name}"><option value="">Pilih ${label.toLowerCase()}</option>${opts.map(x=>`<option ${value===x?'selected':''}>${x}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="${id}" name="${name}" placeholder="Tulis ${label.toLowerCase()}">${esc(value)}</textarea>`:`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${type==='date'?'':`Masukkan ${label.toLowerCase()}`}" ${type==='number'?'min="1"':''}>`}<span class="field-error">Lengkapi kolom ini.</span></div>`}
function renderNew(){let type=state.formType||'active';let fields= type==='active'?`${field('name','Nama lengkap','Rania Aditya')}${field('nim','NIM','23.11.0456')}${field('program','Program studi','Sistem Informasi')}${field('semester','Semester','5','select',['1','2','3','4','5','6','7','8'])}${field('purpose','Keperluan surat','','textarea')}${field('contact','Nomor kontak','0812-3456-7800')}`:type==='event'?`${field('eventName','Nama kegiatan')}${field('organizer','Penyelenggara')}${field('eventDate','Tanggal kegiatan','','date')}${field('location','Lokasi kegiatan')}${field('purpose','Tujuan kegiatan','','textarea')}${field('responsible','Penanggung jawab')}${fileField('proposal','Lampiran proposal (opsional)')}`:`${field('facility','Fasilitas yang dipinjam','','select',['Ruang Seminar B-204','Aula Gedung Utama','Ruang Diskusi A-103'])}${field('eventDate','Tanggal penggunaan','','date')}${field('startTime','Waktu mulai','','time')}${field('endTime','Waktu selesai','','time')}${field('eventName','Nama kegiatan')}${field('participants','Jumlah peserta','','number')}${field('contact','Nomor kontak')}`;return `${header('LAYANAN DIGITAL','Buat Pengajuan','Isi data yang diperlukan. Pengajuanmu akan diteruskan ke verifikator unit.', '')}<div class="form-layout"><section class="card form-card"><div class="form-step"><span class="step-dot active">1</span><span class="step-copy"><b>Pilih layanan</b><span>Jenis permohonan</span></span><span class="step-line"></span><span class="step-dot active">2</span><span class="step-copy"><b>Isi data</b><span>Informasi pendukung</span></span><span class="step-line"></span><span class="step-dot">3</span><span class="step-copy"><b>Tinjau</b><span>Kirim pengajuan</span></span></div><h2 class="form-section-title">Layanan yang dibutuhkan</h2><p class="form-help">Pilih salah satu jenis administrasi di bawah.</p><div class="service-choices">${[['active','▧',SERVICE.active],['event','✳',SERVICE.event],['facility','⌂',SERVICE.facility]].map(([key,ic,label])=>`<button type="button" class="service-choice ${type===key?'selected':''}" data-pick-service="${key}"><span class="service-icon">${ic}</span><b>${label}</b></button>`).join('')}</div><form id="newForm" novalidate><div class="form-grid">${fields}</div><div class="form-actions"><button type="button" class="button button-quiet" id="saveDraft">Simpan Draf</button><button type="submit" class="button button-primary">Tinjau & Kirim <span>→</span></button></div></form></section><aside class="card form-side"><h3>Alur pengajuan</h3>${[['1','Lengkapi formulir','Pastikan informasi sesuai kebutuhan layanan.'],['2','Verifikator memeriksa','Unit terkait akan meninjau pengajuanmu.'],['3','Pantau & akses hasil','Status dan hasil tersimpan di akunmu.']].map(x=>`<div class="guide-step"><span class="guide-number">${x[0]}</span><div><b>${x[1]}</b><span>${x[2]}</span></div></div>`).join('')}<div class="notice"><b>Catatan demo</b><br>Pengajuan ini menggunakan data simulasi. Dokumen hasil merupakan keluaran internal prototipe.</div></aside></div>`}
function fileField(name,label){return `<div class="field" data-field="${name}"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="file" accept=".pdf,.jpg,.jpeg,.png"><small>PDF, JPG, PNG · Maksimal 5 MB per berkas</small><span class="field-error">Periksa tipe dan ukuran berkas.</span></div>`}
function findRequest(id=state.selectedId){return state.requests.find(r=>r.id===id)}
function timelineMarkup(r){return (r.timeline||[]).map(t=>`<div class="timeline-item"><b>${t.title}</b><span>${t.date} · ${t.actor}</span>${t.note?`<p>${esc(t.note)}</p>`:''}</div>`).join('')+`<div class="timeline-item pending"><b>${r.status==='approved'?'Proses selesai':'Menunggu proses berikutnya'}</b><span>Belum ada aktivitas lanjutan</span></div>`}
function renderDetail(){let r=findRequest();if(!r)return `${header('PENGAJUAN','Pengajuan tidak ditemukan','Permohonan ini mungkin sudah tidak tersedia.',primaryLink('requests','Kembali ke riwayat'))}`;let approved=r.status==='approved';let canEdit=r.status==='revision_requested';return `${header('RUANG PENGAJU','Detail Pengajuan',`Dikirim pada ${r.date}. Informasi dan perkembangan pengajuanmu.`,primaryLink('requests','← Kembali'))}<div class="detail-layout"><section class="card detail-card"><div class="detail-overview"><div><div class="subtle-label">${r.id} · ${r.date}</div><h2>${serviceName(r.type)}</h2><p>Pemohon: ${esc(r.name)}</p></div>${status(r.status)}</div>${r.note?`<div class="revision-box"><b>Catatan verifikator</b>${esc(r.note)}</div>`:''}<div class="info-grid">${Object.entries(r.fields||{}).filter(([k])=>k!=='proposal').slice(0,8).map(([k,v])=>`<div class="info-block"><span>${({name:'Nama lengkap',nim:'NIM',program:'Program studi',semester:'Semester',purpose:'Keperluan',contact:'Nomor kontak',eventName:'Nama kegiatan',organizer:'Penyelenggara',eventDate:'Tanggal',location:'Lokasi',responsible:'Penanggung jawab',facility:'Fasilitas',startTime:'Waktu mulai',endTime:'Waktu selesai',participants:'Jumlah peserta'})[k]||k}</span><b>${esc(v)||'—'}</b></div>`).join('')}</div><div class="timeline"><h3>Perjalanan pengajuan</h3>${timelineMarkup(r)}</div></section><aside class="card decision-card"><h3>${approved?'Dokumen tersedia':'Informasi status'}</h3><p>${approved?'Permohonan disetujui. Hasil di bawah adalah dokumen internal demo dan bukan tanda tangan elektronik tersertifikasi.':canEdit?'Perbarui informasi sesuai catatan verifikator, lalu kirim ulang permohonan.':r.status==='rejected'?'Permohonan tidak dapat dilanjutkan. Kamu dapat membuat pengajuan baru.':'Perkembangan akan ditampilkan di sini setelah ada pemeriksaan.'}</p>${approved?`<div class="notice">PDF internal prototipe<br><b>${r.id}-hasil.pdf</b></div><div class="decision-buttons"><button class="button button-primary" id="downloadDoc">Unduh dokumen demo</button></div>`:''}${canEdit?`<div class="decision-buttons"><button class="button button-primary" id="reviseRequest">Perbarui & Kirim Ulang</button></div>`:''}${['submitted','in_review','revision_requested','draft'].includes(r.status)?`<div class="decision-buttons"><button class="button button-quiet" id="cancelRequest">Batalkan pengajuan</button></div>`:''}</aside></div>`}
function renderArchive(){let items=state.requests.filter(r=>r.name==='Rania Aditya'&&r.status==='approved');return `${header('DOKUMEN PRIBADI','Arsip Digital','Dokumen yang disetujui, tersimpan khusus untuk akunmu.') }<section class="card requests-card"><div class="filter-row"><label class="search-control"><span>⌕</span><input id="archiveSearch" placeholder="Cari arsip berdasarkan layanan…"></label><select class="control" id="archiveService"><option value="all">Semua layanan</option>${Object.entries(SERVICE).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><span class="filter-spacer"></span><span class="subtle-label">${items.length} dokumen</span></div>${items.length?recentTable(items):empty('Belum ada dokumen di arsip','Dokumen akan muncul setelah pengajuan disetujui.')}</section>`}
function renderVerifier(){let pending=state.requests.filter(r=>['submitted','in_review'].includes(r.status));let decided=state.requests.filter(r=>['approved','rejected','revision_requested'].includes(r.status)).slice(0,3);return `${header('UNIT AKADEMIK','Dashboard Verifikasi','Selamat bertugas, Dimas. Berikut ringkasan antrean pemeriksaan hari ini.',`<a class="button button-primary" href="#queue">Buka antrean →</a>`)}<div class="stats-grid">${stat('Menunggu pemeriksaan',pending.length,'pengajuan dalam antrean','◷')}${stat('Selesai bulan ini',decided.length,'keputusan tercatat · data demo','✓')}${stat('Rata-rata penanganan','1,8 hari','data simulasi demo','◴')}${stat('Permintaan revisi',state.requests.filter(r=>r.status==='revision_requested').length,'menunggu pembaruan pengaju','↻')}</div><div class="content-grid"><section class="card section-card"><div class="section-head"><div><h3>Perlu ditinjau</h3><p>Pengajuan yang menunggu keputusan</p></div><a class="text-link" href="#queue">Buka antrean →</a></div>${pending.length?recentTable(pending,true):empty('Antrean kosong','Pengajuan baru akan muncul di sini.')}</section><section class="card section-card"><div class="section-head"><div><h3>Aktivitas keputusan</h3><p>Keputusan terbaru dari unit</p></div></div>${decided.length?`<div class="service-list">${decided.map(r=>`<a class="service-item" href="#detail" data-open="${r.id}"><span class="service-icon">${r.status==='approved'?'✓':r.status==='rejected'?'×':'↻'}</span><span class="service-text"><b>${r.id} · ${esc(r.name)}</b><span>${serviceName(r.type)} · ${r.date}</span></span>${status(r.status)}</a>`).join('')}</div>`:empty('Belum ada aktivitas','Keputusan yang dibuat tercatat di sini.')}</section></div>`}
function renderQueue(){let items=state.requests.filter(r=>['submitted','in_review'].includes(r.status));if(state.query)items=items.filter(r=>(r.id+r.name+serviceName(r.type)).toLowerCase().includes(state.query.toLowerCase()));return `${header('UNIT AKADEMIK','Antrean Pengajuan','Periksa kelengkapan dan berikan keputusan dengan catatan yang jelas.') }<section class="card requests-card"><div class="filter-row"><label class="search-control"><span>⌕</span><input id="queueSearch" placeholder="Cari pengaju, ID, atau layanan…" value="${esc(state.query)}"></label><select class="control" id="queueService"><option value="all">Semua layanan</option>${Object.entries(SERVICE).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><span class="filter-spacer"></span><span class="subtle-label">${items.length} menunggu pemeriksaan</span></div>${items.length?recentTable(items,true):empty('Semua pengajuan sudah diperiksa','Pengajuan baru dari pengguna akan muncul di antrean.')}</section>`}
function renderReview(){let r=findRequest();if(!r)return `${header('PEMERIKSAAN','Pengajuan tidak ditemukan','Pilih pengajuan dari antrean verifikasi.',primaryLink('queue','Kembali ke antrean'))}`;let active=['submitted','in_review'].includes(r.status);return `${header('UNIT AKADEMIK','Pemeriksaan Pengajuan',`${r.id} · diterima ${r.date}`,primaryLink('queue','← Kembali ke antrean'))}<div class="detail-layout"><section class="card detail-card"><div class="detail-overview"><div><div class="subtle-label">PENGAJU · ${esc(r.name)}</div><h2>${serviceName(r.type)}</h2><p>Data simulasi untuk pemeriksaan unit</p></div>${status(r.status)}</div><div class="info-grid">${Object.entries(r.fields||{}).map(([k,v])=>`<div class="info-block"><span>${({name:'Nama lengkap',nim:'NIM',program:'Program studi',semester:'Semester',purpose:'Keperluan',contact:'Nomor kontak',eventName:'Nama kegiatan',organizer:'Penyelenggara',eventDate:'Tanggal',location:'Lokasi',responsible:'Penanggung jawab',facility:'Fasilitas',startTime:'Waktu mulai',endTime:'Waktu selesai',participants:'Jumlah peserta'})[k]||k}</span><b>${esc(v)||'—'}</b></div>`).join('')}</div>${r.fields?.proposal?`<div class="notice">Lampiran proposal: ${esc(r.fields.proposal)}</div>`:''}<div class="timeline"><h3>Riwayat pemeriksaan</h3>${timelineMarkup(r)}</div></section><aside class="card decision-card"><h3>Keputusan verifikator</h3>${active?`<p>Pilih keputusan. Permintaan revisi dan penolakan membutuhkan alasan tertulis.</p><div class="field"><label for="decisionNote">Catatan pemeriksaan</label><textarea id="decisionNote" placeholder="Tulis catatan, terutama untuk revisi atau penolakan…"></textarea><span class="field-error" id="decisionError">Alasan wajib diisi untuk keputusan ini.</span></div><div class="decision-buttons"><button class="button button-primary" data-decision="approved">Setujui pengajuan</button><button class="button button-quiet" data-decision="revision_requested">Minta revisi</button><button class="button button-danger" data-decision="rejected">Tolak pengajuan</button></div>`:`<p>Keputusan telah dicatat. Status: ${status(r.status)}</p><div class="revision-box"><b>Catatan keputusan</b>${esc(r.note||'Tidak ada catatan.')}</div>`}</aside></div>`}
function completed(){return state.requests.filter(r=>r.status==='approved').length}
function impactValues(){let n=completed(),sheets=state.requests.filter(r=>r.status==='approved').reduce((sum,r)=>sum+(state.services[r.type]||5),0);let before=sheets*1.8+ n*24;let after=n*(state.transfer*210+13);return {n,sheets,before:Math.round(before),after:Math.round(after),net:Math.round(before-after),cost:sheets*state.paperCost+n*state.printing}}
function impactChartBars(){return `<div class="chart"><span class="axis-label a">800</span><span class="axis-label b">600</span><span class="axis-label c">400</span><span class="axis-label d">200</span><i class="chart-gridline"></i><i class="chart-gridline"></i><i class="chart-gridline"></i><i class="chart-gridline"></i><div class="bar-group">${[['Surat aktif',.81,.31],['Izin kegiatan',.62,.26],['Peminjaman',.72,.34]].map(([name,b,a])=>`<div class="bar-col"><div class="bar-pair"><span class="bar conventional" style="--bar-height:${b*100}%"></span><span class="bar digital" style="--bar-height:${a*100}%"></span></div><span class="bar-label">${name}</span></div>`).join('')}</div></div>`}
function renderImpact(){let d=impactValues();let netLabel=d.net<0?'Kenaikan emisi terestimasi':`${d.net.toLocaleString('id-ID')} gCO₂e`;let trend=[['Mei',.34],['Jun',.5],['Jul',.43],['Agu',.67],['Sep',.59],['Okt',.78]];let pts=trend.map(([m,v],i)=>`${38+i*59},${151-v*112}`).join(' ');return `${header('PENGUKURAN LINGKUNGAN','Dampak Lingkungan','Gambaran estimasi dari proses administrasi digital unit pilot. Semua nilai di bawah adalah simulasi demo.',`<div style="display:flex;gap:8px"><select class="control" id="impactMonth"><option>Oktober 2025</option><option>September 2025</option><option>Agustus 2025</option><option>Semua periode</option></select><a class="button button-quiet" href="#method">Lihat metodologi →</a></div>`)}<div class="impact-disclaimer"><span><b>Estimasi berbasis asumsi · Data simulasi</b><br>Bukan hasil pengukuran kampus atau audit emisi. Cakupan: proses administrasi unit pilot.</span><a href="#method">Cara hitung ⓘ</a></div><div class="impact-kpis">${impactKpi('Dokumen selesai',d.n.toLocaleString('id-ID'),'pengajuan disetujui','▤')}${impactKpi('Kertas dihindari',d.sheets.toLocaleString('id-ID'),'lembar · asumsi per layanan','▧')}${impactKpi('Biaya fisik dihindari',`Rp ${d.cost.toLocaleString('id-ID')}`,'estimasi kertas & pencetakan','◉')}${impactKpi('Emisi konvensional',`${d.before.toLocaleString('id-ID')} g`,'gCO₂e · proses fisik','▧')}${impactKpi('Emisi digital',`${d.after.toLocaleString('id-ID')} g`,'gCO₂e · estimasi operasional','⌁')}${impactKpi(d.net<0?'Perubahan bersih':'Selisih bersih',netLabel,'gCO₂e · sebelum dikurangi sesudah',d.net<0?'↑':'↓')}</div><div class="chart-grid"><section class="card chart-card"><div class="section-head"><div><h3>Perbandingan proses</h3><p>Estimasi emisi · gCO₂e per jenis layanan</p></div></div><div class="legend"><span><i></i>Konvensional</span><span><i class="digital-dot"></i>Digital</span></div>${impactChartBars()}<div class="bar-table-note">Kertas + energi pencetakan dibanding estimasi operasional digital.</div></section><section class="card chart-card"><div class="section-head"><div><h3>Tren enam bulan</h3><p>Emisi proses digital · estimasi bulanan</p></div><select class="control" id="trendMetric"><option>Emisi digital</option><option>Kertas dihindari</option></select></div><svg class="trend-chart" viewBox="0 0 380 180" preserveAspectRatio="none" role="img" aria-label="Tren simulasi emisi digital dari Mei hingga Oktober"><line class="grid" x1="28" y1="20" x2="372" y2="20"/><line class="grid" x1="28" y1="63" x2="372" y2="63"/><line class="grid" x1="28" y1="106" x2="372" y2="106"/><line class="grid" x1="28" y1="149" x2="372" y2="149"/><path class="area" d="M${pts.replaceAll(' ',' L')} L333,160 L38,160 Z"/><polyline class="line" points="${pts}"/>${trend.map(([m,v],i)=>`<circle class="point" cx="${38+i*59}" cy="${151-v*112}" r="3.5"/><text x="${32+i*59}" y="174">${m}</text>`).join('')}</svg></section></div><section class="card section-card"><div class="section-head"><div><h3>Rincian per layanan</h3><p>Periode ${esc(state.month)} · angka bersifat estimasi</p></div><span class="status status-yellow">Data simulasi</span></div><div class="table-wrap"><table><thead><tr><th>JENIS LAYANAN</th><th>SELESAI</th><th>KERTAS (LEMBAR)</th><th>KONVENSIONAL</th><th>DIGITAL</th><th>SELISIH</th></tr></thead><tbody>${Object.entries(SERVICE).map(([k,v],i)=>`<tr><td>${v}</td><td>${i===0?d.n:0}</td><td>${i===0?d.sheets:0} lembar</td><td>${i===0?d.before:0} gCO₂e</td><td>${i===0?d.after:0} gCO₂e</td><td>${i===0?netLabel:'—'}</td></tr>`).join('')}</tbody></table></div>${mobileRequestCards([])}<p class="bar-table-note">Baseline: ${Object.values(state.services).join(' / ')} lembar per layanan. Asumsi dapat disesuaikan admin unit.</p></section>`}
function impactKpi(label,value,foot,icon){return `<article class="card impact-kpi"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`}
function renderMethod(){return `${header('TRANSPARANSI','Metodologi Pengukuran','Cara membaca estimasi, sumber asumsi, serta keterbatasan data yang ditampilkan.') }<div class="method-layout"><aside class="card method-toc"><b>DALAM HALAMAN</b><a href="#scope">Batas perbandingan</a><a href="#baseline">Baseline konvensional</a><a href="#digital">Proses digital</a><a href="#factors">Faktor & sumber</a><a href="#limits">Keterbatasan</a></aside><div class="method-content"><section class="card method-card" id="scope"><div class="page-kicker">01 · RUANG LINGKUP</div><h2>Perbandingan pada proses yang sebanding</h2><p>Dashboard membandingkan proses administrasi fisik (sebelum) dengan proses digital (sesudah) untuk pengajuan yang telah disetujui. Angka demo memakai data simulasi dan tidak mewakili pengukuran operasional Universitas Nusantara.</p><div class="formula">Selisih bersih = Emisi proses konvensional − Emisi operasional digital</div><p>Nilai positif berarti emisi konvensional yang diperkirakan lebih tinggi. Nilai negatif ditampilkan sebagai kenaikan emisi terestimasi, bukan sebagai penghematan.</p></section><section class="card method-card" id="baseline"><div class="page-kicker">02 · PROSES KONVENSIONAL</div><h2>Baseline kertas dan pencetakan</h2><p>Jumlah lembar per layanan dikalikan dengan faktor proses kertas dan energi pencetakan yang diasumsikan untuk unit pilot. Biaya dihitung dari biaya kertas dan pencetakan per layanan.</p><div class="formula">Lembar = pengajuan disetujui × baseline lembar per layanan</div><div class="formula">Emisi konvensional = (lembar × faktor kertas) + energi pencetakan</div><p>Nilai lembar dan biaya saat ini merupakan parameter demo. Ganti dengan hasil observasi layanan dan sumber faktor yang dapat ditelusuri sebelum publikasi.</p></section><section class="card method-card" id="digital"><div class="page-kicker">03 · PROSES DIGITAL</div><h2>Estimasi operasional sederhana</h2><p>Prototipe memakai pendekatan operasional sederhana dengan ukuran transfer representatif sebagai proksi penggunaan digital. Perhitungan belum mengimplementasikan model SWDM v4 lengkap dan tidak memasukkan emisi perangkat pengguna atau seluruh infrastruktur secara terukur.</p><div class="formula">Emisi digital (estimasi) = transfer per alur × faktor listrik × koefisien operasional</div><p>Pengukuran data transfer per perjalanan, perjalanan representatif, dan penggunaan cache belum dikumpulkan. Faktor default hanyalah placeholder demo.</p></section><section class="card method-card" id="factors"><div class="page-kicker">04 · FAKTOR & SUMBER</div><h2>Parameter yang dapat ditelusuri</h2><div class="table-wrap"><table><thead><tr><th>PARAMETER</th><th>NILAI DEMO</th><th>SUMBER / STATUS</th></tr></thead><tbody><tr><td>Baseline kertas</td><td>${Object.values(state.services).join(' / ')} lembar per layanan</td><td class="table-note">Asumsi simulasi. Belum divalidasi dengan observasi unit.</td></tr><tr><td>Biaya kertas</td><td>Rp ${state.paperCost} / lembar</td><td class="table-note">Nilai contoh untuk demonstrasi, bukan harga kampus.</td></tr><tr><td>Faktor listrik jaringan</td><td>${state.gridFactor} gCO₂e/kWh</td><td class="table-note">Placeholder regional demo. Perlu sumber resmi, tahun, dan wilayah.</td></tr><tr><td>Transfer alur</td><td>${state.transfer} MB / alur</td><td class="table-note">Belum diukur. Nilai simulasi untuk prototipe.</td></tr></tbody></table></div><p>Faktor emisi eksternal harus memuat publikasi, wilayah, tahun, batas proses, dan tanggal akses. Tidak ada klaim pengukuran real-time.</p></section><section class="card method-card" id="limits"><div class="page-kicker">05 · KETERBATASAN</div><h2>Apa yang belum dicakup</h2><ul><li>Belum ada observasi proses per layanan atau sampel faktur pencetakan.</li><li>Perjalanan transportasi incremental tidak dihitung karena belum terdokumentasi.</li><li>Ukuran transfer belum diukur dengan browser developer tools atau sampel journey.</li><li>Output digital masih dokumen internal prototipe dan bukan tanda tangan elektronik tersertifikasi.</li><li>Data yang ditampilkan hanyalah data demo lokal, bukan catatan kampus.</li></ul><p>Referensi metode: <a href="https://sustainablewebdesign.org/estimating-digital-emissions/" target="_blank" rel="noreferrer">Sustainable Web Design Model v4 ↗</a> · <a href="https://www.websitecarbon.com/" target="_blank" rel="noreferrer">Website Carbon ↗</a></p></section></div></div>`}
function renderAdmin(){let counts={all:state.requests.length,pending:pendingCount(),approved:completed()};return `${header('UNIT PILOT','Dashboard Admin','Ringkasan layanan administrasi unit dan konfigurasi demo.') }<div class="stats-grid">${stat('Total pengajuan',counts.all,'data demo tersimpan lokal','▤')}${stat('Menunggu verifikasi',counts.pending,'butuh tindak lanjut','◷')}${stat('Disetujui',counts.approved,'termasuk dalam estimasi dampak','✓')}${stat('Layanan aktif','3','cakupan prototipe unit pilot','⌂')}</div><div class="content-grid"><section class="card section-card"><div class="section-head"><div><h3>Aktivitas pengajuan</h3><p>Ringkasan proses demo unit</p></div><a class="text-link" href="#users">Kelola pengguna →</a></div>${recentTable(state.requests.slice(0,4),true)}</section><section class="card section-card"><div class="section-head"><div><h3>Konfigurasi unit</h3><p>Parameter untuk transparansi dampak</p></div></div><div class="service-list"><a class="service-item" href="#baseline"><span class="service-icon">▦</span><span class="service-text"><b>Baseline & layanan</b><span>3 jenis layanan · asumsi demo</span></span><span class="service-arrow">›</span></a><a class="service-item" href="#emission"><span class="service-icon">⌁</span><span class="service-text"><b>Faktor emisi</b><span>Operasional sederhana · demo</span></span><span class="service-arrow">›</span></a><a class="service-item" href="#impact"><span class="service-icon">✳</span><span class="service-text"><b>Laporan dampak</b><span>Data simulasi, bukan hasil audit</span></span><span class="service-arrow">›</span></a></div></section></div>`}
function renderUsers(){const people=[{n:'Rania Aditya',id:'23.11.0456',role:'Pengaju',init:'RA'},{n:'Dimas Pratama',id:'Verifikator · Unit Akademik',role:'Verifikator',init:'DP'},{n:'Nadia Kurnia',id:'Admin · Unit Akademik',role:'Admin',init:'NK'},{n:'Fajar Ramadhan',id:'23.10.0312',role:'Pengaju',init:'FR'}];return `${header('PENGELOLAAN UNIT','Manajemen Pengguna','Atur peran dan status akun demo. Perubahan peran dilakukan oleh admin unit.',`<button class="button button-primary" id="addUser">＋ Tambah Pengguna</button>`)}<section class="card requests-card"><div class="filter-row"><label class="search-control"><span>⌕</span><input id="userSearch" placeholder="Cari nama atau identitas…"></label><select class="control"><option>Semua peran</option><option>Pengaju</option><option>Verifikator</option><option>Admin</option></select><span class="filter-spacer"></span><span class="subtle-label">${people.length} akun demo</span></div><div class="table-wrap"><table><thead><tr><th>PENGGUNA</th><th>IDENTITAS</th><th>PERAN</th><th>STATUS</th><th></th></tr></thead><tbody>${people.map((u,i)=>`<tr data-user-row><td><div class="user-cell"><div class="avatar">${u.init}</div><b>${u.n}</b></div></td><td>${u.id}</td><td><select class="user-role" ${i===2?'disabled':''}><option ${u.role==='Pengaju'?'selected':''}>Pengaju</option><option ${u.role==='Verifikator'?'selected':''}>Verifikator</option><option ${u.role==='Admin'?'selected':''}>Admin</option></select></td><td><span class="status status-green">Aktif</span></td><td><button class="action-link" data-toggle-user="${i}">Nonaktifkan</button></td></tr>`).join('')}</tbody></table></div>${mobileRequestCards([])}<div class="notice">Kontrol peran dan akun hanya simulasi UI. Otorisasi server-side belum diterapkan dalam prototipe frontend ini.</div></section>`}
function renderBaseline(){return `${header('KONFIGURASI UNIT','Layanan & Baseline','Sesuaikan asumsi proses fisik. Setiap angka tetap berlabel simulasi sampai divalidasi.',`<button class="button button-primary" id="saveBaseline">Simpan Konfigurasi</button>`)}<div class="admin-grid"><section class="card admin-card"><h3>Baseline layanan</h3><p>Perkiraan lembar kertas untuk satu layanan yang disetujui.</p>${Object.entries(SERVICE).map(([k,v])=>`<div class="baseline-row"><div><b>${v}</b><br><span>lembar per pengajuan selesai</span></div><input type="number" min="0" data-baseline="${k}" value="${state.services[k]}"><span>lembar</span></div>`).join('')}</section><section class="card admin-card"><h3>Biaya proses fisik</h3><p>Nilai contoh unit pilot. Masukkan asumsi dan sumber observasi setelah tersedia.</p><div class="form-grid">${field('paperCost','Biaya kertas per lembar',state.paperCost,'number')}${field('printingCost','Energi/biaya cetak per layanan',state.printing,'number')}</div><div class="field" style="margin-top:13px">${field('baselineSource','Sumber asumsi','Simulasi UI · belum divalidasi')}</div><div class="field" style="margin-top:13px">${field('effectiveDate','Tanggal berlaku','2025-10-27','date')}</div><div class="notice">Nilai demo tidak mencerminkan data pembelian atau tagihan Universitas Nusantara.</div></section><section class="card admin-card"><h3>Aturan status selesai</h3><p>Dokumen masuk hitungan dampak hanya setelah permohonan disetujui.</p><div class="switch-row"><span>Gunakan status disetujui sebagai selesai</span><span class="switch"><i></i></span></div><div class="switch-row"><span>Hitung perjalanan incremental</span><span class="subtle-label">Tidak dihitung</span></div></section><section class="card admin-card"><h3>Riwayat perubahan</h3><p>Contoh audit perubahan konfigurasi.</p><div class="guide-step"><span class="guide-number">1</span><div><b>Baseline demo dibuat</b><span>27 Okt 2025 · Admin Unit · Nilai simulasi awal</span></div></div></section></div>`}
function renderEmission(){return `${header('KONFIGURASI PENGUKURAN','Faktor Emisi','Pilih metode dan dokumentasikan parameter digital secara transparan.',`<button class="button button-primary" id="saveEmission">Simpan Faktor</button>`)}<div class="admin-grid"><section class="card admin-card"><h3>Metode perhitungan</h3><p>Metode aktif dijelaskan di laporan dan halaman metodologi.</p><div class="field"><label for="methodMode">Mode pengukuran</label><select id="methodMode"><option>Estimasi operasional sederhana</option><option>SWDM v4 lengkap — belum diimplementasikan</option></select></div><div class="field" style="margin-top:13px">${field('methodVersion','Versi metode','1.0-demo')}</div><div class="notice">Mode SWDM v4 lengkap belum diterapkan pada prototipe ini.</div></section><section class="card admin-card"><h3>Faktor listrik jaringan</h3><p>Parameter contoh, belum dilengkapi sumber faktor yang tervalidasi.</p><div class="field">${field('gridFactor','Faktor listrik',state.gridFactor,'number')}</div><div class="field" style="margin-top:13px"><label for="region">Wilayah faktor</label><select id="region"><option>Jamali · placeholder demo</option><option>Global · placeholder demo</option></select></div><div class="field" style="margin-top:13px">${field('factorSource','Sumber faktor','Belum ditetapkan — wajib divalidasi')}</div></section><section class="card admin-card"><h3>Pengukuran perjalanan web</h3><p>Masukkan sampel representatif setelah pengukuran browser tersedia.</p><div class="field">${field('transferSize','Ukuran transfer per alur',state.transfer,'number')}</div><div class="field" style="margin-top:13px">${field('sampleJourneys','Jumlah perjalanan sampel','Belum diukur','number')}</div><div class="field" style="margin-top:13px">${field('measurementDate','Tanggal pengukuran','','date')}</div><div class="notice">Tidak ada data transfer, jumlah perjalanan, atau penggunaan cache yang telah diukur pada demo ini.</div></section><section class="card admin-card"><h3>Histori revisi faktor</h3><p>Perubahan parameter untuk kebutuhan transparansi.</p><div class="guide-step"><span class="guide-number">1</span><div><b>Faktor awal demo</b><span>27 Okt 2025 · Admin Unit · Placeholder simulasi</span></div></div><div class="guide-step"><span class="guide-number">2</span><div><b>Sumber belum divalidasi</b><span>Menunggu verifikasi sumber dan periode faktor.</span></div></div></section></div>`}
function renderProfile(){let user=USERS[state.role];return `${header('AKUN','Profil & Pengaturan','Kelola preferensi tampilan dan informasi akun demo.') }<div class="profile-grid"><section class="card profile-card"><div class="profile-hero"><div class="avatar">${user.initials}</div><div><h2>${user.name}</h2><span>${user.sub}</span></div></div><h3>Informasi profil</h3><p>Identitas akun demo saat ini.</p><div class="inline-form">${field('profileNameField','Nama lengkap',user.name)}${field('profileEmail','Alamat email','rania.aditya@kampus.ac.id','email')}<button class="button button-primary" id="saveProfile">Simpan Profil</button></div></section><section class="card profile-card"><h3>Preferensi tampilan</h3><p>Pengaturan disimpan pada peramban perangkat ini.</p><div class="switch-row"><span>Mode gelap</span><button class="button button-quiet button-small" id="profileTheme">Ganti tema ◐</button></div><div class="switch-row"><span>Bahasa antarmuka</span><b>Bahasa Indonesia</b></div><div class="notice">Preferensi tema adalah pilihan kenyamanan tampilan dan tidak dianggap sebagai bukti penghematan emisi.</div><h3 style="margin-top:18px">Keamanan demo</h3><p>Perubahan kata sandi tidak tersedia pada prototipe.</p><button class="button button-quiet" id="passwordMock">Ubah kata sandi</button></section></div>`}
function renderLanding(){return `<div class="landing"><header class="public-nav"><a class="brand" href="#beranda"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M8 5.5h10l6 6V26H8z"/><path d="M18 5.5v6h6M12 17h8M12 21h5"/><path d="M9 9 5 13v13h14"/></svg></span><span class="brand-copy"><strong>paperless</strong><small>UNIVERSITAS NUSANTARA</small></span></a><nav class="public-links"><a href="#cara-kerja">Cara kerja</a><a href="#layanan">Layanan</a><a href="#transparansi">Transparansi</a></nav><div class="public-actions"><a class="button button-quiet" href="#login">Masuk</a><a class="button button-primary" href="#login">Mulai Pengajuan <span>→</span></a></div></header><section class="landing-hero"><div class="landing-copy"><div class="page-kicker">ADMINISTRASI KAMPUS DIGITAL</div><h1>Administrasi kampus lebih <em>ringkas.</em><br>Dampak lebih terukur.</h1><p>Ajukan kebutuhan akademik, pantau prosesnya, dan akses dokumen dalam satu ruang digital yang praktis.</p><div class="landing-ctas"><a class="button button-primary" href="#login">Mulai Pengajuan <span>→</span></a><a class="button button-quiet" href="#cara-kerja">Lihat Cara Kerja</a></div><div style="font-size:9px;color:var(--muted);margin-top:13px">Prototipe demo · Data dan dampak bersifat simulasi</div></div><div class="landing-illustration" aria-label="Ilustrasi dokumen kertas menjadi berkas digital"><div class="campus-shape"></div><div class="campus-roof"></div><div class="campus-columns"><i></i><i></i><i></i><i></i></div><div class="campus-base"></div><div class="illustration-file"><div class="paper-lines"></div><div class="paper-lines"></div><div class="paper-lines"></div><div class="paper-lines"></div></div><span class="illus-spark a">✳</span><span class="illus-spark b">✦</span><span class="illus-label">Dari lembar ke layanan digital</span></div></section><section class="landing-section" id="cara-kerja"><div class="section-intro"><div class="page-kicker">ALUR YANG JELAS</div><h2>Satu alur, dari pengajuan sampai arsip.</h2><p>Setiap langkah tercatat agar kamu tahu apa yang sudah terjadi dan apa yang perlu dilakukan selanjutnya.</p></div><div class="steps-grid"><article class="card step-card"><div class="step-count">01</div><div><h3>Ajukan kebutuhan</h3><p>Pilih layanan dan lengkapi informasi melalui formulir digital yang ringkas.</p></div></article><article class="card step-card"><div class="step-count">02</div><div><h3>Diverifikasi unit</h3><p>Petugas memeriksa permohonan dan mencatat keputusan beserta alasannya.</p></div></article><article class="card step-card"><div class="step-count">03</div><div><h3>Pantau dan akses</h3><p>Lihat perkembangan, kirim revisi, dan temukan dokumen yang telah disetujui.</p></div></article></div></section><section class="landing-section" id="layanan"><div class="section-intro"><div class="page-kicker">LAYANAN UNIT PILOT</div><h2>Layanan yang kamu butuhkan, dalam satu tempat.</h2><p>Cakupan prototipe saat ini untuk tiga kebutuhan administrasi kampus.</p></div><div class="landing-services">${[['▧',SERVICE.active,'Untuk beasiswa, magang, dan keperluan akademik lainnya.'],['✳',SERVICE.event,'Ajukan izin kegiatan dengan informasi dan lampiran pendukung.'],['⌂',SERVICE.facility,'Ajukan penggunaan ruang dan fasilitas kampus.']].map(x=>`<article class="card landing-service"><div class="service-icon">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join('')}</div></section><section class="landing-section" id="transparansi"><div class="public-method"><span class="mini-icon">✳</span><div><h3>Dampak lingkungan disajikan secara terbuka.</h3><p>Setiap angka adalah estimasi berbasis asumsi dan data simulasi. Metode, batas perbandingan, serta keterbatasan dapat dibaca siapa saja.</p></div><a href="#method">Pahami metodologi →</a></div></section><footer class="public-footer"><span>© 2025 PaperLess Campus · Prototipe Universitas Nusantara</span><span>Dirancang untuk layanan kampus yang lebih mudah ditelusuri.</span></footer></div>`}
function renderLogin(){return `<div class="login-wrap"><section class="login-side"><a class="brand" href="#beranda"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M8 5.5h10l6 6V26H8z"/><path d="M18 5.5v6h6M12 17h8M12 21h5"/></svg></span><span class="brand-copy"><strong>paperless</strong><small>UNIVERSITAS NUSANTARA</small></span></a><div class="login-side-content"><div class="page-kicker" style="color:#e8ad4b">RUANG DIGITAL KAMPUS</div><h1>Urus administrasi, tanpa kehilangan jejak.</h1><p>Ajukan layanan, ikuti proses verifikasi, dan temukan arsipmu. Semua dalam satu ruang yang tertata.</p><div class="login-decoration"></div></div><div class="login-bottom">Prototipe akademik · Data dan akun pada halaman ini adalah simulasi.</div></section><section class="login-form-side"><form class="login-form" id="loginForm"><div class="page-kicker">SELAMAT DATANG</div><h2>Masuk ke akunmu</h2><p>Gunakan mode demo untuk menjelajahi PaperLess Campus.</p><div class="field"><label for="loginEmail">Alamat email</label><input id="loginEmail" type="email" value="rania.aditya@kampus.ac.id" required><span class="field-error">Masukkan alamat email yang valid.</span></div><div class="field"><label for="loginPassword">Kata sandi</label><div class="password-wrap"><input id="loginPassword" type="password" value="demopassword" required><button type="button" class="show-password" id="showPassword">Tampilkan</button></div></div><div class="demo-box"><b>Mode Demo</b><br>Pilih peran untuk mencoba alur berbeda. Tidak ada autentikasi kampus yang terhubung.<div class="field" style="margin-top:9px"><label for="loginRole">Masuk sebagai</label><select id="loginRole"><option value="pengaju">Pengaju · Rania Aditya</option><option value="verifikator">Verifikator · Dimas Pratama</option><option value="admin">Admin Unit · Nadia Kurnia</option></select></div></div><button type="submit" class="button button-primary">Masuk ke Demo <span>→</span></button><p class="login-note">Akun disimulasikan pada perangkat ini. Jangan masukkan kata sandi asli.</p></form></section></div>`}
function render(){renderNav();if(['beranda',''].includes(state.page)){view.innerHTML=renderLanding();$('#mobileNav').style.display='none';document.querySelector('.sidebar').style.display='none';document.querySelector('.main-area').style.marginLeft='0';document.querySelector('.topbar').style.display='none';return}if(state.page==='login'){view.innerHTML=renderLogin();document.querySelector('.sidebar').style.display='none';document.querySelector('.topbar').style.display='none';document.querySelector('.main-area').style.marginLeft='0';$('#mobileNav').style.display='none';return}document.querySelector('.sidebar').style.display='';document.querySelector('.topbar').style.display='';document.querySelector('.main-area').style.marginLeft='';$('#mobileNav').style.display='';const map={dashboard:renderDashboard,requests:renderRequests,new:renderNew,detail:renderDetail,archive:renderArchive,verifier:renderVerifier,queue:renderQueue,review:renderReview,impact:renderImpact,method:renderMethod,admin:renderAdmin,users:renderUsers,baseline:renderBaseline,emission:renderEmission,profile:renderProfile};view.innerHTML=(map[state.page]||map.dashboard)();if(state.page==='impact')$('#impactMonth').value=state.month;syncThemeControl();}
function go(page){state.page=page;if(page!=='requests'&&page!=='queue')state.query='';persist();render();$('#sidebar').classList.remove('open');$('#scrim').classList.remove('open');window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{let page=location.hash.slice(1)||'beranda';state.page=page;if(page==='beranda'||page==='login'){}else if(state.role==='pengaju'&&['admin','users','baseline','emission','verifier','queue','review'].includes(page)){state.page='dashboard';location.hash='dashboard';toast('Halaman ini hanya tersedia untuk peran terkait.')}else if(state.role!=='verifikator'&&['verifier','queue','review'].includes(page)){state.page=state.role==='admin'?'admin':'dashboard';location.hash=state.page}else if(state.role!=='admin'&&['admin','users','baseline','emission'].includes(page)){state.page=state.role==='verifikator'?'verifier':'dashboard';location.hash=state.page}render()});
document.addEventListener('click',e=>{let pick=e.target.closest('[data-pick-service]');if(pick){state.formType=pick.dataset.pickService;render()}let quickService=e.target.closest('[data-service]');if(quickService){state.formType=quickService.dataset.service;state.page='new';location.hash='new';render()}let open=e.target.closest('[data-open]');if(open){state.selectedId=open.dataset.open;state.page=state.role==='verifikator'?'review':'detail';location.hash=state.page;render()}let decision=e.target.closest('[data-decision]');if(decision){let type=decision.dataset.decision,note=$('#decisionNote')?.value.trim()||'';if(type!=='approved'&&!note){$('#decisionError').style.display='block';$('#decisionNote').closest('.field').classList.add('invalid');return}const labels={approved:'Menyetujui pengajuan',revision_requested:'Meminta revisi',rejected:'Menolak pengajuan'};openModal(labels[type],`Keputusan untuk ${state.selectedId} akan dicatat pada riwayat pengajuan.`,type==='approved'?'Setujui pengajuan':'Catat keputusan',()=>applyDecision(type,note),type==='rejected'?'!':'✓');}if(e.target.id==='clearFilters'){state.filter='all';state.query='';render()}if(e.target.id==='cancelRequest'){openModal('Batalkan pengajuan?',`Pengajuan ${state.selectedId} akan ditandai sebagai dibatalkan.`, 'Ya, batalkan',()=>{let r=findRequest();r.status='cancelled';r.timeline.push({title:'Pengajuan dibatalkan',actor:USERS[state.role].name,date:nowDate()});persist();render();toast('Pengajuan dibatalkan')},'!')}if(e.target.id==='reviseRequest'){let r=findRequest();r.status='submitted';r.note='';r.timeline.push({title:'Pengajuan revisi dikirim ulang',actor:USERS.pengaju.name,date:nowDate()});persist();render();toast('Pengajuan berhasil dikirim ulang')}if(e.target.id==='saveDraft')saveApplication(true);if(e.target.id==='downloadDoc'){toast('Dokumen internal demo siap diunduh');downloadDemo(findRequest())}if(e.target.id==='themeToggle'||e.target.id==='profileTheme')toggleTheme();if(e.target.id==='profileMenu'||e.target.id==='topUser')go('profile');if(e.target.id==='notifications')toast('Tidak ada notifikasi baru');if(e.target.id==='addUser')toast('Form tambah pengguna demo');if(e.target.id==='saveBaseline')saveBaseline();if(e.target.id==='saveEmission')saveEmission();if(e.target.id==='saveProfile')toast('Profil demo diperbarui');if(e.target.id==='passwordMock')toast('Perubahan sandi tidak tersedia di mode demo');if(e.target.id==='modalClose'||e.target.id==='modalCancel')closeModal();if(e.target.id==='modalConfirm'){let fn=modalAction;closeModal();fn?.()}if(e.target.id==='menuButton'){$('#sidebar').classList.add('open');$('#scrim').classList.add('open')}if(e.target.id==='scrim'){ $('#sidebar').classList.remove('open');$('#scrim').classList.remove('open')}if(e.target.id==='showPassword'){let p=$('#loginPassword');p.type=p.type==='password'?'text':'password';e.target.textContent=p.type==='password'?'Tampilkan':'Sembunyikan'}if(e.target.closest('[data-toggle-user]'))toast('Status akun demo diperbarui')});
function nowDate(){return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(new Date())+' · '+new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit'}).format(new Date())}
function openModal(title,body,confirm,action,symbol='✓'){modalAction=action;$('#modalTitle').textContent=title;$('#modalBody').textContent=body;$('#modalConfirm').textContent=confirm;$('#modalSymbol').textContent=symbol;$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false')}
function closeModal(){$('#modal').classList.remove('open');$('#modal').setAttribute('aria-hidden','true');modalAction=null}
function applyDecision(type,note){let r=findRequest();if(!r||!['submitted','in_review'].includes(r.status)){toast('Status pengajuan sudah berubah');return}r.status=type;r.note=note;r.timeline.push({title:{approved:'Pengajuan disetujui',revision_requested:'Revisi diminta',rejected:'Pengajuan ditolak'}[type],actor:'Dimas Pratama · Verifikator',date:nowDate(),note});persist();render();toast('Keputusan berhasil dicatat')}
function saveApplication(draft){let form=$('#newForm');if(!form)return;let invalid=false;form.querySelectorAll('.field').forEach(x=>x.classList.remove('invalid'));if(!draft){form.querySelectorAll('.field').forEach(x=>{let el=x.querySelector('input,select,textarea');if(!el)return;if(el.type==='file'){let file=el.files[0];if(file&&(file.size>5*1024*1024||!['application/pdf','image/jpeg','image/png'].includes(file.type))){x.classList.add('invalid');invalid=true}return}if(!el.value.trim()){x.classList.add('invalid');invalid=true}});if(invalid){toast('Lengkapi data atau periksa lampiran');return}}let fields={};form.querySelectorAll('input,select,textarea').forEach(x=>{if(x.name)fields[x.name]=x.type==='file'?(x.files[0]?.name||''):x.value.trim()});if(draft){state.requests.unshift({id:nextId(),type:state.formType||'active',status:'draft',date:nowDate(),name:'Rania Aditya',fields,timeline:[{title:'Draf disimpan',actor:'Rania Aditya',date:nowDate()}]});persist();toast('Draf tersimpan di riwayat');go('requests');return}openModal('Kirim pengajuan?',`Periksa kembali data ${serviceName(state.formType||'active')}. Pengajuan akan masuk ke antrean verifikator demo.`, 'Kirim pengajuan',()=>{state.requests.unshift({id:nextId(),type:state.formType||'active',status:'in_review',date:nowDate(),name:'Rania Aditya',fields,timeline:[{title:'Pengajuan dikirim',actor:'Rania Aditya',date:nowDate()},{title:'Dalam antrean verifikasi',actor:'Sistem',date:nowDate()}]});state.selectedId=state.requests[0].id;persist();go('detail');toast('Pengajuan berhasil dikirim')})}
function nextId(){let max=Math.max(100,...state.requests.map(r=>parseInt(r.id.split('-').pop(),10)||0));return `PL-2025-${String(max+1).padStart(3,'0')}`}
function saveBaseline(){document.querySelectorAll('[data-baseline]').forEach(x=>state.services[x.dataset.baseline]=Number(x.value)||0);state.paperCost=Number($('#field-paperCost')?.value)||state.paperCost;state.printing=Number($('#field-printingCost')?.value)||state.printing;persist();toast('Konfigurasi baseline disimpan');}
function saveEmission(){state.gridFactor=Number($('#field-gridFactor')?.value)||state.gridFactor;state.transfer=Number($('#field-transferSize')?.value)||state.transfer;persist();toast('Faktor demo disimpan');}
function downloadDemo(r){let txt=`Dokumen internal prototipe PaperLess Campus\n\nNomor: ${r.id}\nLayanan: ${serviceName(r.type)}\nPemohon: ${r.name}\nStatus: Disetujui\n\nDokumen ini adalah keluaran internal demo dan bukan dokumen bertanda tangan elektronik tersertifikasi.`;let blob=new Blob([txt],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${r.id}-hasil-demo.txt`;a.click();URL.revokeObjectURL(url)}
function syncThemeControl(){let dark=document.documentElement.dataset.theme==='dark';let label=$('#themeToggle')?.querySelectorAll('span')[1];if(label)label.textContent=dark?'Mode terang':'Mode gelap';let profile=$('#profileTheme');if(profile)profile.textContent=dark?'Gunakan mode terang':'Gunakan mode gelap'}
function toggleTheme(){let root=document.documentElement;let theme=root.dataset.theme==='dark'?'light':'dark';root.dataset.theme=theme;try{localStorage.setItem('paperless-theme',theme)}catch{}syncThemeControl();toast(theme==='dark'?'Mode gelap aktif':'Mode terang aktif')}
document.addEventListener('change',e=>{if(e.target.id==='roleSelect'){state.role=e.target.value;state.page={pengaju:'dashboard',verifikator:'verifier',admin:'admin'}[state.role];state.query='';persist();location.hash=state.page;render();toast(`Mode demo: ${USERS[state.role].sub}`)}if(e.target.id==='loginRole'){}if(e.target.id==='statusFilter'){state.filter=e.target.value;render()}if(e.target.id==='impactMonth'){state.month=e.target.value;render()}if(e.target.id==='archiveService')filterArchive();if(e.target.id==='trendMetric'){let label=$('.chart-card:last-child .section-head p');if(label)label.textContent=e.target.value==='Emisi digital'?'Emisi proses digital · estimasi bulanan':'Lembar kertas dihindari · estimasi bulanan';toast(`Grafik menampilkan ${e.target.value.toLowerCase()}`)}if(e.target.classList.contains('user-role'))toast('Peran demo diperbarui (simulasi)');if(e.target.dataset.userToggle)toast('Status akun demo diperbarui')});
document.addEventListener('input',e=>{if(e.target.id==='requestSearch'||e.target.id==='queueSearch'){state.query=e.target.value;let pos=e.target.selectionStart;render();let el=$('#'+e.target.id);el?.focus();el?.setSelectionRange(pos,pos)}if(e.target.id==='archiveSearch'||e.target.id==='archiveService')filterArchive();if(e.target.id==='userSearch'){let q=e.target.value.toLowerCase();document.querySelectorAll('[data-user-row]').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q)?'':'none')}});
function filterArchive(){let q=$('#archiveSearch')?.value.toLowerCase()||'',type=$('#archiveService')?.value||'all',items=state.requests.filter(r=>r.status==='approved'&&r.name==='Rania Aditya'&&(type==='all'||r.type===type)&&serviceName(r.type).toLowerCase().includes(q));let content=$('.requests-card .table-wrap');if(content)content.innerHTML=`<table><thead><tr><th>ID PENGAJUAN</th><th>LAYANAN</th><th>TANGGAL</th><th>STATUS</th><th></th></tr></thead><tbody>${requestRows(items)}</tbody></table>`;let mobile=$('.requests-card .table-mobile');if(mobile)mobile.outerHTML=mobileRequestCards(items)}
document.addEventListener('submit',e=>{if(e.target.id==='newForm'){e.preventDefault();saveApplication(false)}if(e.target.id==='loginForm'){e.preventDefault();state.role=$('#loginRole').value;state.page={pengaju:'dashboard',verifikator:'verifier',admin:'admin'}[state.role];persist();location.hash=state.page;render();toast(`Mode demo: ${USERS[state.role].sub}`)}});
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#sidebar').classList.remove('open');$('#scrim').classList.remove('open')}});
let savedTheme=null;try{savedTheme=localStorage.getItem('paperless-theme')}catch{}if(savedTheme)document.documentElement.dataset.theme=savedTheme;state.page=location.hash.slice(1)||'beranda';render();
